Release years are absent from the library and playlist records, so each distinct discovered song must be read before creating a reviewed, deduplicated mutation plan for the song library.

```python
library_song_ids = {record["song_id"] for record in song_library_records}
playlist_song_ids = {song["id"] for detail in playlist_details_by_id.values() for song in detail["songs"]}
all_discovered_song_ids = library_song_ids | playlist_song_ids
song_details_by_id = {}
for song_id in sorted(all_discovered_song_ids):
    song_details_by_id[song_id] = apis.spotify.show_song(song_id=song_id)
cutoff_year = 2021
release_year_by_song_id = {song_id: int(detail["release_date"][:4]) for song_id, detail in song_details_by_id.items()}
library_removal_ids = sorted({song_id for song_id in library_song_ids if release_year_by_song_id[song_id] < cutoff_year})
playlist_removal_pairs = sorted({(playlist_id, song["id"]) for playlist_id, detail in playlist_details_by_id.items() for song in detail["songs"] if release_year_by_song_id[song["id"]] < cutoff_year})
print({"distinct_songs_reviewed": len(song_details_by_id), "library_removal_candidates": len(library_removal_ids), "playlist_removal_candidates": len(playlist_removal_pairs)})
```

